<template>
  <div>
    <div class="flex-center">
      <el-form
        style="width: 35%"
        :model="server_config"
        :rules="rules"
        ref="server_config"
        label-width="120px"
        class="mt-20"
        size="small"
      >
        <el-form-item label="备注名称:" prop="gateway_name">
          <el-input v-model="server_config.gateway_name"></el-input>
        </el-form-item>
        <el-form-item label="服务器地址:" prop="address">
          <el-input v-model="server_config.address"></el-input>
        </el-form-item>
        <el-form-item label="心跳周期(秒):" prop="heart_duration">
          <el-input-number
            v-model="server_config.heart_duration"
          ></el-input-number>
        </el-form-item>
        <el-form-item>
          <el-button @click="submitConfigForm('server_config')">提交</el-button>
        </el-form-item>
      </el-form>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    configForm: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    // let validateIP = (rule, value, callback) => {
    //   const reg =
    //     /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    //   if (!reg.test(value)) {
    //     callback(new Error("格式错误 格式:XXX.XXX.XXX.XXX"));
    //   } else {
    //     callback();
    //   }
    // };
    return {
      server_config: {
        heart_duration: 30,
      },
      rules: {
        gateway_name: [{ required: true, message: "请输入", trigger: "blur" }],
        address: [{ required: true, message: "请输入", trigger: "blur" }],
      },
    };
  },
  watch: {
    configForm: {
      handler(val) {
        this.server_config = {
          heart_duration: val.server_config.heart_duration || 30,
          ...val.server_config,
        };
      },
      deep: true,
      immediate: true,
    },
  },
  created() {},
  methods: {
    submitConfigForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$emit("sumbitData", {
            server_config: this.server_config,
          });
        }
      });
    },
    success() {
      this.addThemeVisible = false;
    },
  },
};
</script>

<style lang="scss" scoped></style>
